local function MergeTables(dest, src)
	for k, v in pairs(src) do
		if type(v) == "table" and type(dest[k]) == "table" then
			MergeTables(dest[k], v)
		else
			dest[k] = v
		end
	end
end
ReformInfo = {}
if ReformInfo_data then
	for k, v in pairs(ReformInfo_data) do
		ReformInfo[k] = v
	end
end
if ReformInfo_string then
	for k, v in pairs(ReformInfo_string) do
		if ReformInfo[k] then
			MergeTables(ReformInfo[k], v)
		end
	end
end
